const files = $input.all().map((item) => item.json);
const selected = files.filter((file) => file.type === 'file' && /\.(md|mdx)$/i.test(String(file.name ?? file.path ?? '')));

if (!selected.length) {
  return [{ json: {
    sourceRoute: 'empty',
    outcome: 'error',
    message: 'No Markdown or MDX files were found in the configured GitHub directory.',
  } }];
}

return selected.map((file) => ({ json: { ...file, sourceRoute: 'fetch' } }));

const encoded = String($json.content ?? '').replace(/\s/g, '');
const markdown = Buffer.from(encoded, 'base64').toString('utf8');
const sourcePath = String($json.path ?? $json.name ?? 'unknown.md');

function stripQuotes(value) {
  const text = String(value ?? '').trim();
  if ((text.startsWith('"') && text.endsWith('"')) || (text.startsWith("'") && text.endsWith("'"))) return text.slice(1, -1);
  return text;
}

function parseValue(value) {
  const text = String(value ?? '').trim();
  if (text === 'true') return true;
  if (text === 'false') return false;
  if (text.startsWith('[') && text.endsWith(']')) {
    try { return JSON.parse(text); } catch {
      return text.slice(1, -1).split(',').map(stripQuotes).filter(Boolean);
    }
  }
  return stripQuotes(text);
}

function asList(value) {
  if (Array.isArray(value)) return value.map(String).map((v) => v.trim()).filter(Boolean);
  if (value === undefined || value === null || value === '') return [];
  return String(value).split(',').map((v) => v.trim()).filter(Boolean);
}

function asBoolean(value, fallback = false) {
  if (typeof value === 'boolean') return value;
  if (String(value).toLowerCase() === 'true') return true;
  if (String(value).toLowerCase() === 'false') return false;
  return fallback;
}

function slugify(value) {
  return String(value ?? '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
}

let body = markdown;
const frontmatter = {};
if (markdown.startsWith('---')) {
  const end = markdown.indexOf('\n---', 3);
  if (end >= 0) {
    const block = markdown.slice(3, end).trim();
    body = markdown.slice(end + 4).replace(/^\s+/, '');
    for (const line of block.split(/\r?\n/)) {
      if (!line.trim() || line.trim().startsWith('#')) continue;
      const separator = line.indexOf(':');
      if (separator < 1) continue;
      const key = line.slice(0, separator).trim();
      frontmatter[key] = parseValue(line.slice(separator + 1));
    }
  }
}

const fileName = sourcePath.split('/').pop().replace(/\.(md|mdx)$/i, '');
const heading = body.match(/^#\s+(.+)$/m)?.[1]?.trim();
const title = String(frontmatter.title ?? heading ?? fileName).trim();
const slug = slugify(frontmatter.slug ?? fileName);
const errors = [];
if (!title) errors.push('A title is required');
if (!slug) errors.push('A slug could not be derived');
if (!body.trim()) errors.push('Page content is empty');

return { json: {
  sourcePath,
  sourceSha: String($json.sha ?? ''),
  title,
  slug,
  description: String(frontmatter.description ?? ''),
  folder: String(frontmatter.folder ?? '').trim(),
  categories: asList(frontmatter.categories),
  tags: asList(frontmatter.tags),
  draft: asBoolean(frontmatter.draft, true),
  showOnNav: asBoolean(frontmatter.showOnNav, false),
  showAuthor: asBoolean(frontmatter.showAuthor, false),
  showContributors: asBoolean(frontmatter.showContributors, false),
  heroImage: String(frontmatter.heroImage ?? ''),
  package: String(frontmatter.package ?? 'studiocms/markdown'),
  contentLang: String(frontmatter.contentLang ?? 'default'),
  augments: asList(frontmatter.augments),
  contributorIds: asList(frontmatter.contributorIds),
  content: body,
  errors,
} };

const documents = $input.all().map((item) => ({ ...item.json }));
const counts = new Map();
for (const document of documents) counts.set(document.slug, (counts.get(document.slug) ?? 0) + 1);

return documents.map((document) => {
  const errors = [...(document.errors ?? [])];
  if ((counts.get(document.slug) ?? 0) > 1) errors.push('Duplicate slug in the source collection: ' + document.slug);
  return { json: { ...document, errors, valid: errors.length === 0 } };
});

const documents = $('Validate Markdown Documents').all().map((item) => item.json).filter((document) => document.valid);
const folders = $('Retrieve StudioCMS Folders').all().map((item) => item.json).filter((item) => item.id);
const categories = $('Fetch StudioCMS Categories').all().map((item) => item.json).filter((item) => item.id !== undefined);
const tags = $('Retrieve StudioCMS Tags').all().map((item) => item.json).filter((item) => item.id !== undefined);

const slugify = (value) => String(value ?? '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const folderNames = new Set(folders.map((item) => String(item.name).toLowerCase()));
const categorySlugs = new Set(categories.map((item) => String(item.slug).toLowerCase()));
const tagSlugs = new Set(tags.map((item) => String(item.slug).toLowerCase()));
const actions = [];
const planned = new Set();

for (const document of documents) {
  if (document.folder && !folderNames.has(document.folder.toLowerCase())) {
    const key = 'folder:' + document.folder.toLowerCase();
    if (!planned.has(key)) actions.push({ kind: 'folder', name: document.folder, key });
    planned.add(key);
  }
  for (const name of document.categories) {
    const slug = slugify(name);
    const key = 'category:' + slug;
    if (slug && !categorySlugs.has(slug) && !planned.has(key)) actions.push({ kind: 'category', name, slug, key });
    planned.add(key);
  }
  for (const name of document.tags) {
    const slug = slugify(name);
    const key = 'tag:' + slug;
    if (slug && !tagSlugs.has(slug) && !planned.has(key)) actions.push({ kind: 'tag', name, slug, key });
    planned.add(key);
  }
}

return (actions.length ? actions : [{ kind: 'none', name: 'No taxonomy changes required' }]).map((action) => ({ json: action }));

const documents = $('Validate Markdown Documents').all().map((item) => item.json);
const folders = $('Sync StudioCMS Folders').all().map((item) => item.json).filter((item) => item.id);
const categories = $('Update StudioCMS Categories').all().map((item) => item.json).filter((item) => item.id !== undefined);
const tags = $('Refresh StudioCMS Tags').all().map((item) => item.json).filter((item) => item.id !== undefined);
const pages = $('Fetch Existing StudioCMS Pages').all().map((item) => item.json).filter((item) => item.id);
const config = $('Set GitHub Content Parameters').first().json;

const slugify = (value) => String(value ?? '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
const folderByName = new Map(folders.map((item) => [String(item.name).toLowerCase(), String(item.id)]));
const categoryBySlug = new Map(categories.map((item) => [String(item.slug).toLowerCase(), String(item.id)]));
const tagBySlug = new Map(tags.map((item) => [String(item.slug).toLowerCase(), String(item.id)]));
const pageBySlug = new Map(pages.map((item) => [String(item.slug).toLowerCase(), item]));
const sourceSlugs = new Set(documents.filter((document) => document.valid).map((document) => document.slug.toLowerCase()));

function sorted(values) { return [...values].map(String).sort(); }
function decodedArray(value) {
  if (Array.isArray(value)) return value;
  if (typeof value !== 'string') return [];
  try { const parsed = JSON.parse(value); return Array.isArray(parsed) ? parsed : []; } catch { return []; }
}
function sameArray(left, right) { return JSON.stringify(sorted(left)) === JSON.stringify(sorted(right)); }

const changes = [];
for (const document of documents) {
  if (!document.valid) {
    changes.push({ action: 'error', slug: document.slug || null, title: document.title || null, sourcePath: document.sourcePath, message: document.errors.join('; ') });
    continue;
  }

  const unresolved = [];
  const parentFolderId = document.folder ? folderByName.get(document.folder.toLowerCase()) : '';
  if (document.folder && !parentFolderId) unresolved.push('folder: ' + document.folder);
  const categoryIds = document.categories.map((name) => categoryBySlug.get(slugify(name))).filter(Boolean);
  const tagIds = document.tags.map((name) => tagBySlug.get(slugify(name))).filter(Boolean);
  if (categoryIds.length !== document.categories.length) unresolved.push('one or more categories');
  if (tagIds.length !== document.tags.length) unresolved.push('one or more tags');
  if (unresolved.length) {
    changes.push({ action: 'error', slug: document.slug, title: document.title, sourcePath: document.sourcePath, message: 'Could not resolve ' + unresolved.join(', ') + ' after taxonomy creation.' });
    continue;
  }

  const target = { ...document, parentFolderId: parentFolderId ?? '', categoryIds, tagIds };
  const existing = pageBySlug.get(document.slug.toLowerCase());
  if (!existing) {
    changes.push({ ...target, action: 'create', pageId: null });
    continue;
  }

  const existingCategoryIds = (existing.categories ?? []).map((item) => item.id);
  const existingTagIds = (existing.tags ?? []).map((item) => item.id);
  const existingContent = existing.defaultContent?.content ?? '';
  const unchanged =
    String(existing.title ?? '') === document.title &&
    String(existing.description ?? '') === document.description &&
    String(existing.package ?? '') === document.package &&
    String(existing.contentLang ?? '') === document.contentLang &&
    String(existing.heroImage ?? '') === document.heroImage &&
    String(existing.parentFolder ?? '') === String(parentFolderId ?? '') &&
    Boolean(Number(existing.showOnNav ?? 0)) === document.showOnNav &&
    Boolean(Number(existing.draft ?? 0)) === document.draft &&
    Boolean(Number(existing.showAuthor ?? 0)) === document.showAuthor &&
    Boolean(Number(existing.showContributors ?? 0)) === document.showContributors &&
    sameArray(existingCategoryIds, categoryIds) &&
    sameArray(existingTagIds, tagIds) &&
    sameArray(decodedArray(existing.augments), document.augments) &&
    String(existingContent) === document.content;

  changes.push({ ...target, action: unchanged ? 'skip' : 'update', pageId: String(existing.id) });
}

if (config.draftMissingPages === true) {
  const prefix = String(config.managedSlugPrefix ?? '').trim().toLowerCase();
  if (!prefix) {
    changes.push({ action: 'error', slug: null, title: null, sourcePath: null, message: 'managedSlugPrefix is required when draftMissingPages is enabled.' });
  } else {
    for (const page of pages) {
      const slug = String(page.slug ?? '').toLowerCase();
      const alreadyDraft = Boolean(Number(page.draft ?? 0));
      if (slug.startsWith(prefix) && !sourceSlugs.has(slug) && !alreadyDraft) {
        changes.push({ action: 'draft', slug: page.slug, title: page.title, sourcePath: null, pageId: String(page.id), message: 'Missing from the managed GitHub collection.' });
      }
    }
  }
}

return (changes.length ? changes : [{ action: 'skip', slug: null, title: null, sourcePath: null, message: 'No page changes were required.' }]).map((change) => ({ json: change }));

const results = $input.all().map((item) => item.json).filter((item) => item.outcome);
const taxonomy = $('Identify Missing Taxonomy Elements').all().map((item) => item.json).filter((item) => item.kind && item.kind !== 'none');
const count = (outcome) => results.filter((item) => item.outcome === outcome).length;
const errors = count('error');

return [{ json: {
  ok: errors === 0,
  source: $('Set GitHub Content Parameters').first().json,
  taxonomyCreated: {
    folders: taxonomy.filter((item) => item.kind === 'folder').length,
    categories: taxonomy.filter((item) => item.kind === 'category').length,
    tags: taxonomy.filter((item) => item.kind === 'tag').length,
  },
  counts: {
    created: count('created'),
    updated: count('updated'),
    drafted: count('drafted'),
    skipped: count('skipped'),
    errors,
  },
  results,
  completedAt: new Date().toISOString(),
} }];

const task = $('Execute Page Changes Sequentially').item.json;
const outcomes = { create: 'created', update: 'updated', draft: 'drafted', skip: 'skipped', error: 'error' };
return { json: {
  outcome: outcomes[task.action] ?? 'error',
  action: task.action,
  slug: task.slug ?? null,
  title: task.title ?? null,
  sourcePath: task.sourcePath ?? null,
  pageId: $json.id ?? task.pageId ?? null,
  message: task.message ?? '',
} };

return { json: {
  ok: false,
  source: $('Set GitHub Content Parameters').first().json,
  counts: { created: 0, updated: 0, drafted: 0, skipped: 0, errors: 1 },
  results: [{ outcome: 'error', message: $json.message }],
} };
